// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz the from address, an uint value, and a boolean controlling whether the helper should succeed or revert
    function testFuzz_property(address from, uint256 v, bool calleeShouldRevert) public {
        // keep _tos length small but >0; fuzzing addresses in array: use two entries to show loop behavior
        address[] memory tos = new address[](1);

        // deploy a helper that can be instructed to either succeed or revert on the called selector
        CalleeHelper helper = new CalleeHelper(calleeShouldRevert);
        tos[0] = address(helper);

        // bounds: ensure from is not zero (still admissible if zero, but keep wide)
        // ensure v is any uint (no restriction)
        vm.prank(from);

        bool ok;
        try c.transfer(from, address(helper), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assert): If the callee is set to SUCCEED (calleeShouldRevert == false),
        // then the correct contract MUST NOT revert, so ok must be true. The mutant that inverts the require
        // would revert in that case, making ok == false for some inputs. This single assertion holds for all
        // admissible inputs on the reference and is violated by the mutant when helper succeeds.
        if (!calleeShouldRevert) {
            assertTrue(ok);
        } else {
            // if the callee intentionally reverts, both reference and mutant may revert; we don't assert in that branch
            // but keep the domain wide by allowing both outcomes
            assertTrue(true);
        }
    }
}

// Helper that either succeeds (returns true) for the encoded selector transferFrom(address,address,uint256)
// or reverts, controlled at construction time. When succeeding, it must have a function with exact signature
// so that the low-level call from C decodes properly and returns true.
contract CalleeHelper {
    bool public shouldRevert;
    event Called(address from, address to, uint256 v);

    constructor(bool _shouldRevert) {
        shouldRevert = _shouldRevert;
    }

    // Match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        if (shouldRevert) {
            revert("forced");
        }
        emit Called(from, to, v);
        return true;
    }
}
